SELECT DATE_FORMAT(event_time, 'yyyy-MM') AS event_month, page, COUNT(DISTINCT duration_sec) AS unique_event_types, SUM(CASE WHEN page = '/product' THEN 1 ELSE 0 END) AS product_count, MAX(duration_sec) - MIN(duration_sec) AS duration_sec_range FROM web_events WHERE (duration_sec >= 246 AND session_id = 39) OR event_type != 'page_view' GROUP BY DATE_FORMAT(event_time, 'yyyy-MM'), page
